css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
.split{ display: grid; grid-template-columns: minmax(180px, 1fr) minmax(0, 920px); column-gap: 64px; row-gap: 24px; align-items: start; }
.split-body{ min-width: 0; }
.label{ margin: 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.25; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; max-width: 320px; }
.lead{ margin: 0 0 32px 0; font-family: Switzer, Arial, sans-serif; font-size: 40px; line-height: 1.18; font-weight: 400; letter-spacing: -0.02em; }
.body-text{ margin: 0 0 16px 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.6; font-weight: 400; max-width: 760px; }
.fn{ font-size: 0.62em; line-height: 0; vertical-align: super; }
.fn-link{ color: inherit; text-decoration: none; }
.fn-link:hover{ text-decoration: underline; }
@media screen and (max-width: 991px){.split{ grid-template-columns: minmax(0, 1fr); row-gap: 20px; }
.lead{ font-size: 34px; }}
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }
.label{ font-size: 15px; }
.lead{ font-size: 28px; margin-bottom: 24px; }
.body-text{ font-size: 17px; }}
@media screen and (max-width: 479px){.lead{ font-size: 25px; }}
.llm-section { padding-top: 140px; padding-bottom: 140px; background-color: #d1d1d1; color: #13181d; font-family: Switzer, Arial, sans-serif; scroll-margin-top: 120px; }
.llm-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 56px; margin-top: 64px; }
.llm-column { min-width: 0; }
.llm-column-heading { display: flex; align-items: center; gap: 10px; margin: 0 0 8px 0; font-size: 14px; line-height: 1.3; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; }
.llm-column-icon { display: block; width: 20px; height: 20px; }
.llm-list { margin: 0; padding: 0; list-style: none; }
.llm-item { margin: 0; padding: 22px 0; border-top: 1px solid rgba(19, 24, 29, 0.22); }
.llm-item-title { margin: 0 0 8px 0; font-size: 20px; line-height: 1.35; font-weight: 500; }
.llm-item-text { margin: 0; font-size: 16px; line-height: 1.55; color: rgba(19, 24, 29, 0.82); }

@media screen and (max-width: 991px) {
  .llm-section { padding-top: 112px; padding-bottom: 112px; }
  .llm-columns { gap: 40px; margin-top: 48px; }
}
@media screen and (max-width: 767px) {
  .llm-section { padding-top: 88px; padding-bottom: 88px; }
  .llm-columns { grid-template-columns: minmax(0, 1fr); gap: 48px; }
  .llm-item-title { font-size: 19px; }
}
